import{_ as p,C as e,c as l,o as i,b0 as n,G as b,w as r,a as c}from"./chunks/framework.JcZxIv1X.js";const d="data:image/png;base64,",t="/computer-docs/assets/image-20251026194510831.BZF7lMs-.png",m="/computer-docs/assets/image-20251026194549017.DtGxr-TX.png",u="/computer-docs/assets/image-20251026194634138.B-HHABLR.png",A=JSON.parse('{"title":"LV007-第7章-更灵活的定位内存地址的方法","description":null,"frontmatter":{"title":"LV007-第7章-更灵活的定位内存地址的方法","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93c1ff6f50d51","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.961Z","fulluuid":"ff6f50d511fc4834bd129b547fe6cb97","useduuid":"ff6f50d51"}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93c1ff6f50d51.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV007-第7章-更灵活的定位内存地址的方法.md","lastUpdated":1767424849000}'),o={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93c1ff6f50d51.md"};function h(g,s,v,x,k,y){const a=e("center");return i(),l("div",null,[s[1]||(s[1]=n(`<h1 id="lv007-第7章-更灵活的定位内存地址的方法" tabindex="-1">LV007-第7章-更灵活的定位内存地址的方法 <a class="header-anchor" href="#lv007-第7章-更灵活的定位内存地址的方法" aria-label="Permalink to &quot;LV007-第7章-更灵活的定位内存地址的方法&quot;">​</a></h1><p>前面，我们用[0]、[bx]的方法，在访问内存的指令中，定位内存单元的地址。本章我们主要通过具体的问题来讲解一些更灵活的定位内存地址的方法和相关的编程方法。</p><h2 id="_7-1-and-和-or-指令" tabindex="-1">7.1 and 和 or 指令 <a class="header-anchor" href="#_7-1-and-和-or-指令" aria-label="Permalink to &quot;7.1 and 和 or 指令&quot;">​</a></h2><p>首先，介绍两条指令 and 和 or，因为我们下面的例程中要用到它们。</p><h4 id="_7-1-1-and" tabindex="-1">7.1.1 and <a class="header-anchor" href="#_7-1-1-and" aria-label="Permalink to &quot;7.1.1 and&quot;">​</a></h4><p>(1) and 指令：<strong>逻辑与指令</strong>，<strong>按位进行与运算</strong>。</p><p>例如指令：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> mov al,01100011B</span></span>
<span class="line"><span> and al,00111011B</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>执行后：al = 00100011B</p><p>通过该指令可将操作对象的相应位设为 0，其他位不变。例如：</p><p>将 al 的第 6 位设为 0 的指令是：<code>and al,10111111B</code></p><p>将 al 的第 7 位设为 0 的指令是：<code>and al,01111111B</code></p><p>将 al 的第 0 位设为 0 的指令是：<code>and al,11111110B</code></p><h4 id="_7-1-2-or" tabindex="-1">7.1.2 or <a class="header-anchor" href="#_7-1-2-or" aria-label="Permalink to &quot;7.1.2 or&quot;">​</a></h4><p>(2)or 指令：<strong>逻辑或指令，按位进行或运算</strong>。</p><p>例如指令：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov al,01100011B</span></span>
<span class="line"><span>or al,00111011B</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>执行后：al = 01111011B</p><p>通过该指令可将操作对象的相应位设为 1，其他位不变。例如：</p><p>将 al 的第 6 位设为 1 的指令是：<code>or al,01000000B</code></p><p>将 al 的第 7 位设为 1 的指令是：<code>or al,10000000B</code></p><p>将 al 的第 0 位设为 1 的指令是：<code>or al,00000001B</code></p><h2 id="_7-2-关于-ascii-码" tabindex="-1">7.2 关于 ASCII 码 <a class="header-anchor" href="#_7-2-关于-ascii-码" aria-label="Permalink to &quot;7.2 关于 ASCII 码&quot;">​</a></h2><p>计算机中，所有的信息都是二进制，而人能理解的信息是已经具有约定意义的字符。而我们要把这些信息存储在计算机中，就要对其进行编码，将其转化为二进制信息进行存储。而计算机要将这些存储的信息再显示给我们看，就要再对其进行解码。只要编码和解码采用同样的规则，我们就可以将人能理解的信息存入到计算机，再从计算机中取出。</p><p>世界上有很多编码方案，有一种方案叫做 ASCII 编码，是在计算机系统中通常被采用的。简单地说，所谓编码方案，就是一套规则，它约定了用什么样的信息来表示现实对象。比如说，在 ASCII 编码方案中，用 61H 表示“a”，30H 表示数字“0”。</p><p>一个文本编辑过程中，就包含着按照 ASCII 编码规则进行的编码和解码。在文本编辑过程中，我们按一下键盘的 a 键，就会在屏幕上看到“a”。这是怎样一个过程呢？我们按下键盘的 a 键，这个按键的信息被送入计算机，计算机用 ASCII 码的规则对其进行编码，将其转化为 61H 存储在内存的指定空间中；文本编辑软件从内存中取出 61H，将其送到显卡上的显存中；工作在文本模式下的显卡，用 ASCII 码的规则解释显存中的内容，61H 被当作字符“a”，显卡驱动显示器，将字符“a”的图像画在屏幕上。我们可以看到，显卡在处理文本信息的时候，是按照 ASCII 码的规则进行的。这也就是说，如果我们要想在显示器上看到“a”，就要给显卡提供“a”的 ASCII 码，61H。如何提供？当然是写入显存中。</p><h2 id="_7-3-以字符形式给出的数据" tabindex="-1">7.3 以字符形式给出的数据 <a class="header-anchor" href="#_7-3-以字符形式给出的数据" aria-label="Permalink to &quot;7.3 以字符形式给出的数据&quot;">​</a></h2><p>我们可以在汇编程序中，用 <code>&#39;......&#39;</code> 的方式指明数据是以字符的形式给出的，编译器将把它们转化为相对应的 ASCII 码。如下面的程序。</p><p>【<strong>程序 7.3</strong>】</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:code,ds:data</span></span>
<span class="line"><span>data segment </span></span>
<span class="line"><span>    db &#39;unIX&#39; </span></span>
<span class="line"><span>    db &#39;foRK&#39; </span></span>
<span class="line"><span>data ends </span></span>
<span class="line"><span>code segment </span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov al,&#39;a&#39;</span></span>
<span class="line"><span>    mov bl,&#39;b&#39; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov ax,4c00h </span></span>
<span class="line"><span>    int 21h </span></span>
<span class="line"><span>code ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>上面的源程序中：</p><p>“db &#39;unIX&#39;” 相当于“db 75H,6EH,49H,58H”， “u”、“n”, “I”、“X” 的 ASCII 码分别为 75H、6EH、49H、58H;</p><p>“db &#39;foRK&#39;”相当于“db 66H,6FH,52H,4BH”,“f”、“o”、“R”、 “K”的 ASCII 码分别为 66H、6FH、52H、4BH;</p><p>“mov al,&#39;a&#39;”相当于“mov al,61H”，“a”的 ASCII 码为 61H;</p><p>“mov bl,&#39;b&#39;”相当于“mov al,62H”，“b”的 ASCII 码为 62H。</p><p>将程序 7.3 编译为可执行文件后，用 Debug 加载查看 data 段中的内容，如图 7.3 所示。</p><p><img src="`+d+'" alt="image-20251026190514235"></p>',37)),b(a,{style:{color:"#C0C0C0"}},{default:r(()=>[...s[0]||(s[0]=[c(" 图 7.3 查看 data 段中的内容 ",-1)])]),_:1}),s[2]||(s[2]=n(`<p>图 7.3 中，先用 r 命令分析一下 data 段的地址，因“ds = 075A”，所以程序从 076AH 段开始，data 段又是程序中的第一个段，它就在程序的起始处，所以它的段地址为 076AH.</p><p>用 d 命令查看 data 段，Debug 以十六进制数码和 ASCII 码字符的形式显示出其中的内容，从中，可以看出 data 段中的每个数据所对应的 ASCII 字符。</p><h2 id="_7-4-大小写转换的问题" tabindex="-1">7.4 大小写转换的问题 <a class="header-anchor" href="#_7-4-大小写转换的问题" aria-label="Permalink to &quot;7.4 大小写转换的问题&quot;">​</a></h2><p>下面考虑这样一个问题，在 codesg 中填写代码，将 datasg 中的第一个字符串转化为大写，第二个字符串转化为小写。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs: codesg, ds: datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;BasiC&#39;</span></span>
<span class="line"><span>    db &#39;iNfOrMaTiOn&#39;</span></span>
<span class="line"><span>datasg ends </span></span>
<span class="line"><span>codesg segment </span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    ;/*Code Answer*/</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>首先分析一下，我们知道同一个字母的大写字符和小写字符对应的 ASCII 码是不同的，比如“A”的 ASCII 码是 41H，“a”的 ASCII 码是 61H。要改变一个字母的大小写，实际上就是要改变它所对应的 ASCII 码。我们可以将所有的字母的大写字符和小写字符所对应的 ASCII 码列出来，进行一下对比，从中找到规律。</p><table tabindex="0"><thead><tr><th>大写</th><th>十六进制</th><th>二进制</th><th>小写</th><th>十六进制</th><th>二进制</th></tr></thead><tbody><tr><td>A</td><td>41</td><td>0100 0001</td><td>a</td><td>61</td><td>0110 0001</td></tr><tr><td>B</td><td>42</td><td>0100 0010</td><td>b</td><td>62</td><td>0110 0010</td></tr><tr><td>C</td><td>43</td><td>0100 0011</td><td>c</td><td>63</td><td>0110 0011</td></tr><tr><td>D</td><td>44</td><td>0100 0100</td><td>d</td><td>64</td><td>0110 0100</td></tr><tr><td>E</td><td>45</td><td>0100 0101</td><td>e</td><td>65</td><td>0110 0101</td></tr><tr><td>F</td><td>46</td><td>0100 0110</td><td>f</td><td>66</td><td>0110 0110</td></tr><tr><td>...</td><td></td><td></td><td>...</td><td></td><td></td></tr></tbody></table><p>通过对比，我们可以看出来，小写字母的 ASCII 码值比大写字母的 ASCII 码值大 20H。这样，我们可以想到，如果将“a”的 ASCII 码值减去 20H，就可以得到“A”；如果将“A”的 ASCII 码值加上 20H 就可以得到“a”。按照这样的方法，可以将 datasg 段中的第一个字符串“BaSiC”中的小写字母变成大写，第二个字符串“iNfOrMaTiOn”中的大写字母变成小写。</p><p>要注意的是，对于字符串“BaSiC”，应只对其中的小写字母所对应的 ASCII 码进行减 20H 的处理，将其转为大写，而对其中的大写字母不进行改变；对于字符串“iNfOrMaTiOn”，我们应只对其中的大写字母所对应的 ASCII 码进行加 20H 的处理，将其转为小写，而对于其中的小写字母不进行改变。这里面就存在着一个前提，<strong>程序必须要能够判断一个字母是大写还是小写</strong>。以“BaSiC”讨论，程序的流程将是这样的：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg, ds:datasg </span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;Basic&#39; </span></span>
<span class="line"><span>    db &#39;iNfOrMaTiOn&#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0 </span></span>
<span class="line"><span>    mov cx,5</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,[bx]</span></span>
<span class="line"><span>    ;如果(al)&gt;61H,则为小写字母的 ASCII 码，则：sub al,20H</span></span>
<span class="line"><span>    mov [bx], al</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    ;... ...</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p>判断将用到一些我们目前还没有学习到的指令。现在面临的问题是，用已学的指令来解决这个问题，则 <strong>不能对字母的大小写进行任何判断</strong>。</p><p>但是，现实的问题却要求程序必须要能区别对待大写字母和小写字母。那么怎么办呢？</p><p>如果一个问题的解决方案，使我们陷入一种矛盾之中。那么，很可能是我们考虑问题的出发点有了问题，或是说，我们起初运用的规律并不合适。</p><p>我们前面所运用的规律是，小写字母的 ASCII 码值，比大写字母的 ASCII 码值大 20H。考虑问题的出发点是：大写字母 +20H = 小写字母，小写字母 -20H = 大写字母。这使我们最终落入了这样一个矛盾之中：必须判断是大写字母还是小写字母，才能决定进行何种处理，而我们现在又没有可以使用的用于判断的指令。</p><p>我们应该重新观察，寻找新的规律。可以看出，就 ASCII 码的二进制形式来看，除第 5 位（<strong>位数从 0 开始计算</strong>）外，大写字母和小写字母的其他各位都一样。<strong>大写字母 ASCII 码的第 5 位为 0，小写字母的第 5 位为 1</strong>。这样，我们就有了新的方法，一个字母，不管它原来是大写还是小写，将它的第 5 位置 0，它就必将变为大写字母；将它的第 5 位置 1，它就必将变为小写字母。在这个方法中，我们不需要在处理前判断字母的大小写。比如：对于“BaSiC”中的“B”，按要求，它已经是大写字母了，不应进行改变，将它的第 5 位设为 0，它还是大写字母，因为它的第 5 位本来就是 0。</p><p>自然想到我们刚刚学过的 or 和 and 指令将一个数据中的某一位置 0 还是置 1，完整的程序如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg, ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;BasiC&#39;</span></span>
<span class="line"><span>    db &#39;iNfOrMaTiOn&#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax, datasg</span></span>
<span class="line"><span>    mov ds, ax          ;设置 ds 指向 datasg 段</span></span>
<span class="line"><span>    mov bx,0            ;设置(bx)=0,ds:bx 指向&#39;BaSiC&#39;的第一个字母 </span></span>
<span class="line"><span>    mov cx,5            ;设置循环次数 5，因为&#39;BaSiC&#39;有 5 个字母</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al, [bx]        ;将 ASCII 码从 ds:bx 所指向的单元中取出</span></span>
<span class="line"><span>    and al,11011111B    ;将 al 中的 ASCII 码的第 5 位置为 0，变为大写字母</span></span>
<span class="line"><span>    mov [bx], al        ;将转变后的 ASCII 码写回原单元</span></span>
<span class="line"><span>    inc bx              ;(bx)加 1，ds:bx 指向下一个字母</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov bx,5            ;设置(bx)=5,ds:bx 指向&#39;iNfOrMaTiOn&#39;的第一个字母 </span></span>
<span class="line"><span>    mov cx,11           ;设置循环次数 11，因为&#39;iNfOrMaTiOn&#39;有 11 个字母</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    mov al,[bx]</span></span>
<span class="line"><span>    or al,00100000B     ;将 al 中的 ASCII 码的第 5 位置为 1，变为小写字母</span></span>
<span class="line"><span>    mov [bx],al</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s0</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><h2 id="_7-5-bx-idata" tabindex="-1">7.5 [bx+idata] <a class="header-anchor" href="#_7-5-bx-idata" aria-label="Permalink to &quot;7.5 \\[bx+idata]&quot;">​</a></h2><p>在前面，我们用[bx]的方式来指明一个内存单元，还可以用一种更为灵活的方式来指明内存单元：<code>[bx+idata]</code> 表示一个内存单元，它的偏移地址为(bx)+idata(bx 中的数值加上 idata).</p><p>我们看一下指令 <code>mov ax,[bx+200]</code> 的含义：</p><p>将一个内存单元的内容送入 ax，这个内存单元的长度为 2 个字节（字单元），存放一个字，偏移地址为 bx 中的数值加上 200，段地址在 ds 中。</p><p>数学化的描述为：(ax)=((ds)*16+(bx)+200)</p><p>该指令也可以写成如下格式（常用）：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,[200+bx]</span></span>
<span class="line"><span>mov ax,200[bx]</span></span>
<span class="line"><span>mov ax,[bx].200</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="问题-7-1" tabindex="-1">问题 7.1 <a class="header-anchor" href="#问题-7-1" aria-label="Permalink to &quot;问题 7.1&quot;">​</a></h4><p>用 Debug 查看内存，结果如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2000:1000 BE 00 06 00 00 00 ......</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>写出下面的程序执行后，ax、bx、cx 中的内容。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,2000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov bx,1000H</span></span>
<span class="line"><span>mov ax,[bx]</span></span>
<span class="line"><span>mov cx,[bx+1]</span></span>
<span class="line"><span>add cx,[bx+2]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>分析</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, [bx]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址在 bx 中，(bx)= 1000H；指令执行后(ax)= 00BEH。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov cx,[bx+1]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+1 = 1001H；指令执行后(сx)= 0600H.</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add cx,[bx+2]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+2 = 1002H；指令执行后(cx)= 0606H.</p><h2 id="_7-6-用-bx-idata-的方式进行数组的处理" tabindex="-1">7.6 用[bx+idata]的方式进行数组的处理 <a class="header-anchor" href="#_7-6-用-bx-idata-的方式进行数组的处理" aria-label="Permalink to &quot;7.6 用\\[bx+idata]的方式进行数组的处理&quot;">​</a></h2><p>有了[bx+idata]这种表示内存单元的方式，我们就可以用更高级的结构来看待所要处理的数据。</p><p>问题：在 codesg 中填写代码，将 datasg 中定义的第一个字符串转化为大写，第二个字符串转化为小写。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs: codesg, ds: datasg </span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;Basic </span></span>
<span class="line"><span>    db &#39;MinIX&#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    ;/*Code Answer*/</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>按照我们原来的方法，用[bx]的方式定位字符串中的字符。代码段中的程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax </span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov cx,5</span></span>
<span class="line"><span>S:</span></span>
<span class="line"><span>    mov al,[bx]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx],al</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov bx,5 </span></span>
<span class="line"><span>    mov cx,5</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    mov al,[bx]</span></span>
<span class="line"><span>    or al,00100000b</span></span>
<span class="line"><span>    mov [bx],al</span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>现在，我们有了[bx+idata]的方式，就可以用更简化的方法来完成上面的程序。观察 datasg 段中的两个字符串，一个的起始地址为 0，另一个的起始地址为 5。我们可以将这两个字符串看作两个数组，一个从 0 地址开始存放，另一个从 5 开始存放。那么我们可以用[0+bx]和[5+bx]的方式在同一个循环中定位这两个字符串中的字符。在这里，0 和 5 给定了两个字符串的起始偏移地址，bx 中给出了从起始偏移地址开始的相对地址。这两个字符串在内存中的起始地址是不一样的，但是，它们中的每一个字符，从起始地址开始的相对地址的变化是相同的。改进的程序如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax </span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov cx, 5</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,[bx]         ;定位第一个字符串中的字符</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx],al</span></span>
<span class="line"><span>    mov al,[5+bx]       ;定位第二个字符串中的字符</span></span>
<span class="line"><span>    or al,00100000b</span></span>
<span class="line"><span>    mov [5+bx],al </span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>程序也可以写成下面的样子：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov cx,5</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,0[bx]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov 0[bx],al</span></span>
<span class="line"><span>    mov al,5[bx]</span></span>
<span class="line"><span>    or al,00100000b</span></span>
<span class="line"><span>    mov 5[bx],al </span></span>
<span class="line"><span>    inc bx</span></span>
<span class="line"><span>    loop s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>如果用高级语言，比如 C 语言来描述上面的程序，大致是这样的：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Basic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MinIX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OxDE;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>如果你熟悉 C 语言的话，可以比较一下这个 C 程序和上面的汇编程序的相似之处。尤其注意它们定位字符串中字符的方式。</p><p>C 语言：<code>a[i], b[i]</code></p><p>汇编语言：<code>0[bx], 5[bx]</code></p><p>通过比较，我们可以发现，[bx+idata]的方式为高级语言实现数组提供了便利机制。</p><h2 id="_7-7-si-和-di" tabindex="-1">7.7 SI 和 DI <a class="header-anchor" href="#_7-7-si-和-di" aria-label="Permalink to &quot;7.7 SI 和 DI&quot;">​</a></h2><p>si 和 di 是 8086CPU 中和 bx 功能相近的寄存器，si 和 di <strong>不能够分成两个 8 位寄存器来使用</strong>。下面的 3 组指令实现了相同的功能。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;第一组</span></span>
<span class="line"><span>mov bx,0</span></span>
<span class="line"><span>mov ax,[bx]</span></span>
<span class="line"><span>;第二组</span></span>
<span class="line"><span>mov si,0</span></span>
<span class="line"><span>mov ax,[si]</span></span>
<span class="line"><span>;第三组</span></span>
<span class="line"><span>mov di,0</span></span>
<span class="line"><span>mov ax,[di]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>下面的 3 组指令也实现了相同的功能。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;第一组</span></span>
<span class="line"><span>mov bx,0</span></span>
<span class="line"><span>mov ax,[bx+123]</span></span>
<span class="line"><span>;第二组</span></span>
<span class="line"><span>mov si,0</span></span>
<span class="line"><span>mov ax,[si+123]</span></span>
<span class="line"><span>;第三组</span></span>
<span class="line"><span>mov di,0</span></span>
<span class="line"><span>mov ax,[di+123]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h4 id="问题-7-2" tabindex="-1">问题 7.2 <a class="header-anchor" href="#问题-7-2" aria-label="Permalink to &quot;问题 7.2&quot;">​</a></h4><p>用 si 和 di 实现将字符串&#39;welcome to masm！&#39;复制到它后面的数据区中。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;welcome to masm!&#39;</span></span>
<span class="line"><span>    db &#39;................&#39;</span></span>
<span class="line"><span>datasg ends</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>分析：</p><p>现在我们要对 datasg 段中的数据进行复制，先来看一下要复制的数据在什么地方，datasg: 0，这是要进行复制的数据的地址。那么复制到哪里去呢？它后面的数据区。“welcome to masm！”从偏移地址 0 开始存放，长度为 16 个字节，所以，它后面的数据区的偏移地址为 16，就是字符串“................”存放的空间。清楚了地址之后，我们就可以进行处理了。我们用 ds: si 指向要复制的 <strong>源始字符串</strong>，用 ds: di 指向 <strong>复制的目的空间</strong>，然后用一个循环来完成复制。代码段如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>codesg segment </span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov di,16</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov cx,8</span></span>
<span class="line"><span>S:</span></span>
<span class="line"><span>    mov ax,[si]</span></span>
<span class="line"><span>    mov [di],ax</span></span>
<span class="line"><span>    add si,2</span></span>
<span class="line"><span>    add di,2</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>注意，在程序中，用 16 位寄存器进行内存单元之间的数据传送，<strong>一次复制 2 个字节</strong>，一共循环 8 次。</p><h4 id="问题-7-3" tabindex="-1">问题 7.3 <a class="header-anchor" href="#问题-7-3" aria-label="Permalink to &quot;问题 7.3&quot;">​</a></h4><p>用更少的代码，实现问题 7.2 中的程序。</p><p>分析：</p><p>我们可以利用[bx(si 或 di)+idata]的方式，来使程序变得简洁。程序如下（只需要 si 寄存器，不需要 di 了）。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov cx,8</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov ax,0[si]</span></span>
<span class="line"><span>    mov 16[si],ax</span></span>
<span class="line"><span>    add si,2</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h2 id="_7-8-bx-si-和-bx-di" tabindex="-1">7.8 [bx+si]和[bx+di] <a class="header-anchor" href="#_7-8-bx-si-和-bx-di" aria-label="Permalink to &quot;7.8 \\[bx+si]和\\[bx+di]&quot;">​</a></h2><p>在前面，我们用[bx(si 或 di)]和[bx(si 或 di)+idata]的方式来指明一个内存单元，我们还可以用更为灵活的方式：[bx+si]和[bx+di]。</p><p>[bx+si]和[bx+di]的含义相似，我们以[bx+si]为例进行讲解。</p><p>[bx+si]表示一个内存单元，它的偏移地址为(bx)+(si)(即 bx 中的数值加上 si 中的数值)。</p><p>指令 <code>mov ax,[bx+si]</code> 的含义如下：</p><p>将一个内存单元的内容送入 ax，这个内存单元的长度为 2 字节（字单元），存放一个字，偏移地址为 bx 中的数值加上 si 中的数值，段地址在 ds 中。</p><p>数学化的描述为：(ax)=((ds)*16+(bx)+(si))</p><p>该指令也可以写成如下格式（常用）：</p><p><code>mov ax, [bx][si]</code></p><h4 id="问题-7-4" tabindex="-1">问题 7.4 <a class="header-anchor" href="#问题-7-4" aria-label="Permalink to &quot;问题 7.4&quot;">​</a></h4><p>用 Debug 查看内存，结果如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2000:1000 BE 00 06 00 00 00 ... ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>写出下面的程序执行后，ax、bx、cx 中的内容。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,2000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov bx,1000H</span></span>
<span class="line"><span>mov si,0</span></span>
<span class="line"><span>mov ax,[bx+si]</span></span>
<span class="line"><span>inc si</span></span>
<span class="line"><span>mov cx,[bx+si]</span></span>
<span class="line"><span>inc si</span></span>
<span class="line"><span>mov di,si</span></span>
<span class="line"><span>add cx,[bx+di]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>分析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,[bx+si]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(si)= 1000H；指令执行后(ax)= 00BEH。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov cx, [bx+si]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(si)= 1001H；指令执行后(cx)= 0600H。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add cx, [bx+di]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(si)= 1002H；指令执行后(cx)= 0606H。</p><p>只有第三行修改了 bx，指令执行后(bx) = 1000H。</p><h2 id="_7-9-bx-si-idata-和-bx-di-idata" tabindex="-1">7.9 [bx+si+idata]和[bx+di+idata] <a class="header-anchor" href="#_7-9-bx-si-idata-和-bx-di-idata" aria-label="Permalink to &quot;7.9 \\[bx+si+idata]和\\[bx+di+idata]&quot;">​</a></h2><p>[bx+si+idata]和[bx+di+idata]的含义相似，我们以[bx+si+idata]为例进行讲解。</p><p>[bx+si+idata]表示一个内存单元，它的偏移地址为(bx)+(si)+idata。</p><p>指令 <code>mov ax,[bx+si+idata]</code> 的含义如下：</p><p>将一个内存单元的内容送入 ax，这个内存单元的长度为 2 字节（字单元），存放一个字，偏移地址为 bx 中的数值加上 si 中的数值再加上 idata，段地址在 ds 中。</p><p>数学化的描述为：(ax)=((ds)*16+(bx)+(si)+idata)</p><p>该指令也可以写成如下格式（常用）：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,[bx+200+si]</span></span>
<span class="line"><span>mov ax,[200+bx+si]</span></span>
<span class="line"><span>mov ax,200[bx][si]</span></span>
<span class="line"><span>mov ax,[bx].200[si]</span></span>
<span class="line"><span>mov ax, [bx][si].200</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="问题-7-5" tabindex="-1">问题 7.5 <a class="header-anchor" href="#问题-7-5" aria-label="Permalink to &quot;问题 7.5&quot;">​</a></h4><p>用 Debug 查看内存，结果如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2000:1000 BE 00 06 00 6A 22 ... ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>写出下面的程序执行后，ax、bx、cx 中的内容。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,2000H</span></span>
<span class="line"><span>mov ds,ax</span></span>
<span class="line"><span>mov bx,1000H</span></span>
<span class="line"><span>mov si,0</span></span>
<span class="line"><span>mov ax,[bx+2+si]</span></span>
<span class="line"><span>inc si</span></span>
<span class="line"><span>mov cx,[bx+2+si]</span></span>
<span class="line"><span>inc si</span></span>
<span class="line"><span>mov di,si</span></span>
<span class="line"><span>mov bx,[bx+2+di]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>分析：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, [bx+2+si]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(si)+2 = 1002H；指令执行后(ax)= 0006H。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov cx, [bx+2+si]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(si)+2 = 1003H；指令执行后(cx)= 6A00H。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov bx, [bx+2+di]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>访问的字单元的段地址在 ds 中，(ds)= 2000H；偏移地址 =(bx)+(di)+2 = 1004H；指令执行后(bx)= 226AH。</p><h2 id="_7-10-不同的寻址方式的灵活应用" tabindex="-1">7.10 不同的寻址方式的灵活应用 <a class="header-anchor" href="#_7-10-不同的寻址方式的灵活应用" aria-label="Permalink to &quot;7.10 不同的寻址方式的灵活应用&quot;">​</a></h2><p>如果我们比较一下前面用到的几种定位内存地址的方法（可称为寻址方式），就可以发现：</p><ol><li>[idata]用一个常量来表示地址，可用于直接定位一个内存单元；</li><li>[bx]用一个变量来表示内存地址，可用于间接定位一个内存单元；</li><li>[bx+idata]用一个变量和常量表示地址，可在一个起始地址的基础上用变量间接定位一个内存单元；</li><li>[bx+si]用两个变量表示地址；</li><li>[bx+si+idata]用两个变量和一个常量表示地址。</li></ol><p>可以看到，从[idata]一直到[bx+si+idata]，我们可以用 <strong>更加灵活的方式来定位一个内存单元的地址</strong>。这使我们可以从更加结构化的角度来看待所要处理的数据。下面我们通过一个问题的系列来体会 CPU 提供多种寻址方式的用意，并学习一些相关的编程技巧。</p><h4 id="问题-7-6" tabindex="-1">问题 7.6 <a class="header-anchor" href="#问题-7-6" aria-label="Permalink to &quot;问题 7.6&quot;">​</a></h4><p>编程，将 datasg 段中每个单词的头一个字母改为大写字母。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;1. file         &#39;</span></span>
<span class="line"><span>    db &#39;2. edit         &#39;</span></span>
<span class="line"><span>    db &#39;3. search       &#39;</span></span>
<span class="line"><span>    db &#39;4. view         &#39;</span></span>
<span class="line"><span>    db &#39;5. options      &#39;</span></span>
<span class="line"><span>    db &#39;6. help         &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    ;/*Code Answer*/</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start </span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>分析：</p><p>datasg 中的数据的存储结构，如图 7.2 所示。</p><p>我们可以看到，在 datasg 中定义了 6 个字符串，每个长度为 16 个字节（注意，为了直观，每个字符串的后面都加上了空格符，以使它们的长度刚好为 16 个字节）。因为它们是连续存放的，可以将这 6 个字符串看成一个 6 行 16 列的二维数组。按照要求，需要修改每一个单词的第一个字母，即二维数组的每一行的第 4 列(相对于行首的偏移地址为 3)。</p><p><img src="`+t+`" alt="image-20251026194510831"></p><p>我们需要进行 6 次循环，用一个变量 R 定位行，用常量 3 定位列。处理的过程如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    R=第一行的地址</span></span>
<span class="line"><span>    mov cx,6</span></span>
<span class="line"><span>S:</span></span>
<span class="line"><span>    改变 R 行，3 列的字母为大写</span></span>
<span class="line"><span>    R=下一行的地址</span></span>
<span class="line"><span>    loop s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>我们用 bx 作变量，定位每行的起始地址，用 3 定位要修改的列，用[bx+idata]的方式来对目标单元进行寻址，程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;1. file         &#39;</span></span>
<span class="line"><span>    db &#39;2. edit         &#39;</span></span>
<span class="line"><span>    db &#39;3. search       &#39;</span></span>
<span class="line"><span>    db &#39;4. view         &#39;</span></span>
<span class="line"><span>    db &#39;5. options      &#39;</span></span>
<span class="line"><span>    db &#39;6. help         &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start: </span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov cx,6</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,[bx+3]       ;定位 R 行，第 3 列字母传入 al 中</span></span>
<span class="line"><span>    and al,11011111b    ;第 R 行，第 3 列字母改成大写</span></span>
<span class="line"><span>    mov [bx+3],al       ;传回结果</span></span>
<span class="line"><span>    add bx,16              ;下一行</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00h</span></span>
<span class="line"><span>    int 21h</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><h4 id="问题-7-7" tabindex="-1">问题 7.7 <a class="header-anchor" href="#问题-7-7" aria-label="Permalink to &quot;问题 7.7&quot;">​</a></h4><p>编程，将 datasg 段中每个单词改为大写字母。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>db &#39;ibm             &#39;</span></span>
<span class="line"><span>db &#39;dec             &#39;</span></span>
<span class="line"><span>db &#39;dos             &#39;</span></span>
<span class="line"><span>db &#39;vax             &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment </span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    ;/*Code Answer?*/</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>分析：</p><p>datasg 中的数据的存储结构如图 7.3 所示。</p><p><img src="`+m+`" alt="image-20251026194549017"></p><p>在 datasg 中定义了 4 个字符串，每个长度为 16 个字节（注意，为了使我们在 Debug 中可以直观地查看，每个字符串的后面都加上了空格符，以使它们的长度刚好为 16 个字节）。因为它们是连续存放的，我们可以将这 4 个字符串看成一个 4 行 16 列的二维数组。按照要求，我们需要修改每一个单词，即二维数组的每一行的前 3 列。</p><p>我们需要进行 4×3 次的二重循环，用变量 R 定位行，变量 C 定位列。外层循环按行来进行，内层按列来进行。首先用 R 定位第 1 行，然后循环修改 R 行的前 3 列；然后再用 R 定位到下一行，再次循环修改 R 行的前 3 列··· ···，如此重复直到所有的数据修改完毕。处理的过程大致如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    R=第一行的地址；</span></span>
<span class="line"><span>    mov cx,4 </span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    C=第一列的地址</span></span>
<span class="line"><span>    mov cx,3 </span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    改变 R 行，C 列的字母为大写</span></span>
<span class="line"><span>    C=下一列的地址；</span></span>
<span class="line"><span>    loop s </span></span>
<span class="line"><span>    R=下一行的地址</span></span>
<span class="line"><span>    loop s0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>我们用 bx 来作变量，定位每行的起始地址，用 si 定位要修改的列，用[bx+si]的方式来对目标单元进行寻址，程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>db &#39;ibm             &#39;</span></span>
<span class="line"><span>db &#39;dec             &#39;</span></span>
<span class="line"><span>db &#39;dos             &#39;</span></span>
<span class="line"><span>db &#39;vax             &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment </span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov cx,3</span></span>
<span class="line"><span>S:</span></span>
<span class="line"><span>    mov al,[bx+si]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx+si],al</span></span>
<span class="line"><span>    inc si</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    add bx,16</span></span>
<span class="line"><span>    loop s0</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00H</span></span>
<span class="line"><span>    int 21H</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br></div></div><h4 id="问题-7-8" tabindex="-1">问题 7.8 <a class="header-anchor" href="#问题-7-8" aria-label="Permalink to &quot;问题 7.8&quot;">​</a></h4><p>然而，上面的程序有个问题。</p><p>分析：</p><p>问题在于 cx 的使用，我们进行二重循环，却只用了一个循环计数器，造成在进行内层循环的时候，覆盖了外层循环的循环计数值。多用一个计数器又不可能，因为 loop 指令默认 cx 为循环计数器。怎么办呢？</p><p>我们应该在 <strong>每次开始内层循环的时候，将外层循环的 cx 中的数值保存起来</strong>，在 <strong>执行外层循环的 loop 指令前，再恢复外层循环的 cx 数值</strong>。可以用寄存器 dx 来临时保存 cx 中的数值，改进的程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s0: </span></span>
<span class="line"><span>    mov dx,cx       ;将外层循环的 cx 值保存在 dx 中</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov cx,3        ;cx 设置为内层循环的次数</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,[bx+si]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx+si],al</span></span>
<span class="line"><span>    inc si</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    add bx,16</span></span>
<span class="line"><span>    mov cx,dx           ;用 dx 中存放的外层循环的计数值恢复 cx</span></span>
<span class="line"><span>    loop s0             ;外层循环的 loop 指令将 cx 中的计数值减 1</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov ax,4c00H</span></span>
<span class="line"><span>    int 21H</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><p>上面的程序用 dx 来暂时存放 cx 中的值，如果在内层循环中，dx 寄存器也被使用，该怎么办？我们似乎可以使用别的寄存器，但是 CPU 中的寄存器数量毕竟是有限的，如 8086CPU 只有 14 个寄存器。在上面的程序中， si、cx、ax、bx，显然不能用来暂存 cx 中的值，因为这些寄存器在循环中也要使用；cs、ip、ds 也不能用，因为 cs: ip 时刻指向当前指令，ds 指向 datasg 段；可用的就只有：dx、di、es、ss、sp、bp 等 6 个寄存器了。可是如果循环中的程序比较复杂，这些寄存器也都被使用的话，那么该如何？</p><p>我们在这里讨论的问题是，程序中经常需要进行数据的暂存，怎样做将更为合理。这些数据可能是寄存器中的，也可能是内存中的。我们可以用寄存器暂存它们，但是这不是一个一般化的解决方案，因为寄存器的数量有限，每个程序中可使用的寄存器都不一样。我们希望寻找一个通用的方案，来解决这种在编程中经常会出现的问题。</p><p>显然，我们不能选择寄存器，那么可以使用的就是内存了。可以考虑 <strong>将需要暂存的数据放到内存单元中，需要使用的时候，再从内存单元中恢复</strong>。这样我们就需要开辟一段内存空间。再次改进的程序如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg, ds:datasg </span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;ibm             &#39;</span></span>
<span class="line"><span>    db &#39;dec             &#39;</span></span>
<span class="line"><span>    db &#39;dos             &#39;</span></span>
<span class="line"><span>    db &#39;vax             &#39;</span></span>
<span class="line"><span>    dw 0                   ;定义一个字，用来暂存 cx</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    mov ds:[40H],cx     ;将外层循环的 cx 值保存在 datasg:40H 单元中</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov cx,3            ;cx 设置为内层循环的次数</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    mov al,[bx+si]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx+si],al</span></span>
<span class="line"><span>    inc si</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    add bx,16</span></span>
<span class="line"><span>    mov cx,ds:[40H]     ;用 datasg:40H 单元中的值恢复 cx </span></span>
<span class="line"><span>    loop s0             ;外层循环的 loop 指令将 cx 中的计数值减 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov ax,4c00H</span></span>
<span class="line"><span>    int 21H</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div><p>上面的程序中，用内存单元来保存数据，可是上面的做法却有些麻烦，因为如果需要保存多个数据的时候，你必须要记住数据放到了哪个单元中，这样程序容易混乱。</p><p>我们使用内存来暂存数据，这一点是确定了的，但是值得推敲的是，我们用怎样的结构来保存这些数据，而使得我们的程序更加清晰。<strong>一般来说，在需要暂存数据的时候，我们都应该使用栈。</strong> 回忆一下，栈空间在内存中，采用相关的指令，如 push、pop 等，可对其进行特殊的操作。下面，再次改进我们的程序。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg,ds:datasg,ss:stacksg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;ibm             &#39;</span></span>
<span class="line"><span>    db &#39;dec             &#39;</span></span>
<span class="line"><span>    db &#39;dos             &#39;</span></span>
<span class="line"><span>    db &#39;vax             &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>stacksg segment         ;定义一个段，用来做栈段，容量为 16 个字节</span></span>
<span class="line"><span>    dw 0,0,0,0,0,0,0,0</span></span>
<span class="line"><span>stacksg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    mov ax,stacksg</span></span>
<span class="line"><span>    mov ss,ax</span></span>
<span class="line"><span>    mov sp,16</span></span>
<span class="line"><span>    mov ax,datasg</span></span>
<span class="line"><span>    mov ds,ax</span></span>
<span class="line"><span>    mov bx,0</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    push cx         ;将外层循环的 cx 值压栈</span></span>
<span class="line"><span>    mov si,0</span></span>
<span class="line"><span>    mov cx,3        ;cx 设置为内层循环的次数</span></span>
<span class="line"><span>S:</span></span>
<span class="line"><span>    mov al,[bx+si]</span></span>
<span class="line"><span>    and al,11011111b</span></span>
<span class="line"><span>    mov [bx+si],al</span></span>
<span class="line"><span>    inc si</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    add bx,16</span></span>
<span class="line"><span>    pop cx          ;从栈顶弹出原 cx 的值，恢复 cx</span></span>
<span class="line"><span>    loop s0         ;外层循环的 loop 指令将 cx 中的计数值减 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    mov ax, 4c00H</span></span>
<span class="line"><span>    int 21H</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br></div></div><h4 id="问题-7-9" tabindex="-1">问题 7.9 <a class="header-anchor" href="#问题-7-9" aria-label="Permalink to &quot;问题 7.9&quot;">​</a></h4><p>编程，将 datasg 段中每个单词的前 4 个字母改为大写字母</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume cs:codesg, ss:stacksg, ds:datasg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>stacksg segment</span></span>
<span class="line"><span>    dw 0,0,0,0,0,0,0,0 </span></span>
<span class="line"><span>stacksg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>datasg segment</span></span>
<span class="line"><span>    db &#39;1. display      &#39;</span></span>
<span class="line"><span>    db &#39;2. brows        &#39;</span></span>
<span class="line"><span>    db &#39;3. replace      &#39;</span></span>
<span class="line"><span>    db &#39;4. modify       &#39;</span></span>
<span class="line"><span>datasg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>codesg segment</span></span>
<span class="line"><span>start:</span></span>
<span class="line"><span>    ;/*Code Answer*/</span></span>
<span class="line"><span>codesg ends</span></span>
<span class="line"><span></span></span>
<span class="line"><span>end start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>分析：</p><p>datasg 中的数据的存储结构，如图 7.4 所示。</p><p><img src="`+u+`" alt="image-20251026194634138"></p><p>在 datasg 中定义了 4 个字符串，每个长度为 16 字节（注意，为了使我们在 Debug 中可以直观地查看，每个字符串的后面都加上了空格符，以使它们的长度刚好为 16 个字节）。因为它们是连续存放的，我们可以将这 4 个字符串看成一个 4 行 16 列的二维数组，按照要求，我们需要修改每个单词的前 4 个字母，即二维数组的每一行的 3~6 列。</p><p>我们需要进行 4×4 次的二重循环，用变量 R 定位行，常量 3 定位每行要修改的起始列，变量 C 定位相对于起始列的要修改的列。外层循环按行来进行，内层按列来进行。我们首先用 R 定位第 1 行，循环修改 R 行的 3+C(0 &lt; C &lt; 3)列；然后再用 R 定位到下一行，再次循环修改 R 行的 3+C(0≤C≤3)列… …，如此重复直到所有的数据修改完毕。处理的过程大致如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    R=第一行的地址；</span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s0:</span></span>
<span class="line"><span>    C=第一个要修改的列相对于起始列的地址</span></span>
<span class="line"><span>    mov cx,4</span></span>
<span class="line"><span>s:</span></span>
<span class="line"><span>    改变 R 行，3+C 列的字母为大写</span></span>
<span class="line"><span>    C=下一个要修改的列相对于起始列的地址</span></span>
<span class="line"><span>    loop s</span></span>
<span class="line"><span>    R=下一行的地址</span></span>
<span class="line"><span>    loop s0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>我们用 bx 来作变量，定位每行的起始地址，用 si 定位要修改的列，用[bx+3+si]的方式来对目标单元进行寻址。</p><p>请在实验中自己完成这个程序。</p><p>这一章中，我们主要讲解了更灵活的寻址方式的应用和一些编程方法，主要内容有：</p><ul><li>寻址方式[bx(或 si、 di)+idata]、[bx+si(或 di)]、[bx+si(或 di)+idata]的意义和应用；</li><li>二重循环问题的处理；</li><li>栈的应用；</li><li>大小写转化的方法；</li><li>and、or 指令。</li></ul><p>下一章中，我们将对寻址方式的问题进行更深入的探讨。之所以如此重视这个问题，是因为寻址方式的适当应用，使我们可以以更合理的结构来看待所要处理的数据。而为所要处理的看似杂乱的数据设计一种清晰的数据结构是程序设计的一个关键的问题。</p>`,164))])}const E=p(o,[["render",h]]);export{A as __pageData,E as default};
